const body = $input.first().json.body || {};
const clips = (Array.isArray(body.clips) ? body.clips : []).slice(0, 24);
const brand = body.brand || {};
const style = body.style || {};
const target = Number(body.length) || 30;
const NL = String.fromCharCode(10);
const avg = Math.max(0.5, Math.min(5, Number(style.avgShotLength) || 2));
const bpm = Number(style.bpm) >= 60 && Number(style.bpm) <= 180 ? Number(style.bpm) : 100;
const beat = Math.round(6000 / bpm) / 100;
const fracs = clips.length > 12 ? [0.15, 0.4, 0.65, 0.9] : [0.1, 0.3, 0.5, 0.7, 0.9];
const at = (c, f) => Math.round((Number(c.duration) || 2) * f * 10) / 10;
const ext = new RegExp('[.][a-z0-9]+$', 'i');
const frame = (c, sec) => String(c.url).replace('/upload/', '/upload/so_' + sec + ',w_480/').replace(ext, '.jpg');
const notes = style.editorNotes || style.summary || 'Cinematic travel film: unhurried, beautiful frames, cuts that land on the music, very little text.';
const prompt = [
  'You are a senior film editor and copywriter. Cut a ' + target + '-second brand film for the travel company below from the supplied clips, in the editing style of a reference film.',
  'Company: ' + (brand.name || '') + '. Tagline: ' + (brand.tagline || '') + '. Call to action: ' + (brand.cta || '') + '.',
  '',
  'REFERENCE STYLE (match its feel closely): ' + notes,
  'Reference numbers: average shot ' + avg + 's; shot length range ' + JSON.stringify(style.shotLengthRange || [1, 4]) + 's; pacing: ' + (style.pacing || 'builds slowly') + '; camera feel: ' + (style.motion || 'smooth') + '.',
  'The music is ' + bpm + ' BPM, so one beat is ' + beat + ' seconds. Every shot length must be a whole number of beats.',
  '',
  'THE FOOTAGE: each clip has an id, a duration, and frames labelled with their timestamps. Clips are in upload order, which may follow the order they were shot.',
  '',
  'STORY (this matters most):',
  '- First work out what actually happened on this trip from the frames: the places, the people, the meals, the weather, the time of day.',
  '- Build one story with a beginning, a middle and an end. Not a random montage.',
  '- Beginning: arrive. One establishing shot that says where we are. Middle: the days unfold; move through places and moments in an order that feels like travelling, keep shots from the same place together, let the time of day move forward. End: the emotional high point, then one quiet closing shot.',
  '- Every shot must move the story forward. Leave out clips that do not fit. Never put two shots from the same clip back to back.',
  '- Pick each in-point where the action or composition is strongest, judged from the frame timestamps. Fill about ' + (target - 3) + ' seconds.',
  '- Contrast neighbours: wide then close, still then moving, landscape then people.',
  '- effect per shot: "zoomIn" or "zoomOut" for a slow push on still, scenic shots; "none" for shots that already move.',
  '',
  'COPY (on-screen words):',
  '- Write the way Apple writes. Plain words. Sentence case. Short declarative sentences that end with a full stop. Never all caps. No exclamation marks, no hashtags, no emoji, no ellipses.',
  '- Write like a person who was on this trip, about what is truly in the footage. Specific and understated. A little dry wit is welcome.',
  '- Banned words and phrases: unforgettable, adventure, awaits, hidden gems, breathtaking, journey, explore, discover, escape, wanderlust, memories, experience, stunning, epic, vibes.',
  '- title: 2 to 4 words, shown over the opening shot.',
  '- Put a line of copy on 3 to 5 shots only (the caption field), 2 to 6 words each. Read in order, the lines should form one continuous thought about the trip. Every other caption is an empty string.',
  '- captionPosition for each line of copy: put it where the frame has calm empty space (sky, water, road, a plain wall) and never over a face or the main subject. One of top, topLeft, topRight, left, center, right, bottomLeft, bottom, bottomRight. Vary it from line to line.',
  '- Lines of copy are always white, so only place them over areas dark or busy enough for white text to read clearly.',
  '- titlePosition: the same placement choice for the title on the opening shot. titleTone: "light" for white text, or "dark" for near-black text only if the title sits on a bright, plain area such as pale sky.',
  '- The lines must make sense read in the order they appear. If they mention times of day, places or stages of the trip, those must move forward, never backwards, and each line must match what is on screen in its own shot.',
  '- endLine: one closing line of at most 6 words that lands the story. It must not repeat the call to action or the tagline.',
  '- caption (top level): two short sentences for the social post in the same voice. hashtags: 3 to 5, lower case.',
  '',
  '- story: one sentence describing the arc you built.',
  '- landscapeClips: ids of every clip whose frames are wider than they are tall.',
  'Return only JSON, no code fences: {"story":"","title":"","titlePosition":"center","titleTone":"light","endLine":"","caption":"","hashtags":[],"landscapeClips":[],"shots":[{"clipId":"","start":0,"length":0,"effect":"none","caption":"","captionPosition":"bottom"}]}'
].join(NL);
const content = [{ type: 'text', text: prompt }];
for (const c of clips) {
  content.push({ type: 'text', text: 'Clip ' + c.id + ', duration ' + c.duration + ' seconds.' });
  for (const f of fracs) {
    const sec = at(c, f);
    content.push({ type: 'text', text: c.id + ' at ' + sec + 's:' });
    content.push({ type: 'image', source: { type: 'url', url: frame(c, sec) } });
  }
}
return [{ json: { request: { model: 'claude-opus-5-5', max_tokens: 12000, messages: [{ role: 'user', content }] } } }];

const body = $('Clips arrive').first().json.body || {};
const clips = Array.isArray(body.clips) ? body.clips : [];
const brand = body.brand || {};
const style = body.style || {};
const target = Number(body.length) || 30;
const vertical = (body.shape || 'vertical') !== 'landscape';

// 1. Plan from the AI director, with a safe fallback
let plan = null;
let director = 'fallback';
try {
  const ai = $('AI director (Claude)').first().json || {};
  const text = (ai.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  if (text) {
    const a = text.indexOf('{');
    const z = text.lastIndexOf('}');
    const p = JSON.parse(a >= 0 && z > a ? text.slice(a, z + 1) : text);
    if (p && Array.isArray(p.shots) && p.shots.length) { plan = p; director = 'claude'; }
  }
} catch (e) {}
if (!plan && body.plan && Array.isArray(body.plan.shots) && body.plan.shots.length) { plan = body.plan; director = 'request'; }
if (!plan) {
  const shots = [];
  let total = 0;
  for (const c of clips) {
    const dur = Number(c.duration) || 2;
    const len = Math.min(2, dur);
    if (total + len > target - 3.5) break;
    shots.push({ clipId: c.id, start: Math.max(0, Math.min(1, dur - len)), length: len, caption: '' });
    total += len;
  }
  plan = { title: brand.tagline || brand.name || '', caption: brand.tagline || '', hashtags: [], shots };
}

// 2. Style from the reference video
const fade = style.transition === 'fade';
const filter = ['boost', 'contrast', 'muted', 'greyscale', 'darken', 'lighten'].includes(style.filter) ? style.filter : null;
const bpm = Number(style.bpm) >= 60 && Number(style.bpm) <= 180 ? Number(style.bpm) : 100;
const beat = 60 / bpm;
const effects = ['zoomIn', 'zoomOut', 'slideLeft', 'slideRight', 'slideUp', 'slideDown'];
const W = vertical ? 1080 : 1920;
const H = vertical ? 1920 : 1080;
const base = Math.min(W, H);
const r2 = n => Math.round(n * 100) / 100;

// 3. Typography: positioned, animated, with hierarchy
const anchors = ['top', 'topLeft', 'topRight', 'left', 'center', 'right', 'bottomLeft', 'bottom', 'bottomRight'];
const mkText = (text, size, start, length, anchor, o) => {
  o = o || {};
  const pos = anchors.includes(anchor) ? anchor : 'bottom';
  const isL = pos === 'left' || pos.indexOf('Left') > 0;
  const isR = pos === 'right' || pos.indexOf('Right') > 0;
  const isT = pos.indexOf('top') === 0;
  const isB = pos.indexOf('bottom') === 0;
  const asset = {
    type: 'text', text: String(text),
    width: Math.round(W * (o.w || (isL || isR ? 0.72 : 0.88))), height: Math.round(H * (o.h || 0.16)),
    font: { family: 'Montserrat SemiBold', color: o.tone === 'dark' ? '#111111' : '#ffffff', size },
    alignment: { horizontal: isL ? 'left' : (isR ? 'right' : 'center'), vertical: 'center' }
  };
  if (o.bg) asset.background = o.bg;
  const clip = {
    asset, start: r2(start), length: r2(Math.max(0.4, length)), position: pos,
    offset: { x: r2((isL ? 0.07 : (isR ? -0.07 : 0)) + (o.dx || 0)), y: r2((isT ? -0.09 : (isB ? 0.11 : 0)) + (o.dy || 0)) },
    transition: { in: o.tin || 'fade', out: 'fade' }
  };
  if (o.opacity) clip.opacity = o.opacity;
  return clip;
};

// 4. Cut list, snapped to the beat
let t = 0;
const videoClips = [];
const textClips = [];
const cleanShots = [];
const bgClips = [];
const land = new Set(Array.isArray(plan.landscapeClips) ? plan.landscapeClips : []);
let lastSrc = null;
let lastClip = null;
for (const s of plan.shots) {
  const c = clips.find(x => x.id === s.clipId);
  if (!c) continue;
  const dur = Number(c.duration) || Number(s.length) || 2;
  let length = Number(s.length) || 2;
  length = Math.max(beat, Math.round(length / beat) * beat);
  length = r2(Math.max(0.4, Math.min(length, dur)));
  if (t + length > target - 3.2 && videoClips.length >= 3) break;
  const trim = r2(Math.max(0, Math.min(Number(s.start) || 0, Math.max(0, dur - length))));
  const src = String(c.url).replace('/upload/', '/upload/q_auto:best,c_limit,w_1920,h_1920/');
  const hasDims = c.width && c.height;
  const wide = hasDims ? Number(c.width) > Number(c.height) : land.has(c.id);
  const mismatch = vertical ? wide : (hasDims ? Number(c.height) > Number(c.width) : false);
  const v = { asset: { type: 'video', src, trim, volume: 0 }, start: r2(t), length, fit: mismatch ? 'contain' : 'cover' };
  if (mismatch) bgClips.push({ asset: { type: 'video', src, trim, volume: 0 }, start: r2(t), length, fit: 'cover', filter: 'blur' });
  if (fade) v.transition = { in: 'fade', out: 'fade' };
  if (filter) v.filter = filter;
  if (effects.includes(s.effect)) v.effect = s.effect;
  videoClips.push(v);
  let shownCaption = '';
  if (videoClips.length === 1 && (plan.title || brand.name)) {
    const a = anchors.includes(plan.titlePosition) ? plan.titlePosition : 'center';
    if (brand.name && plan.title) textClips.push(mkText(brand.name, Math.round(base * 0.03), t + 0.2, length - 0.2, a, { tone: plan.titleTone, dy: 0.075, opacity: 0.85, h: 0.06 }));
    textClips.push(mkText(plan.title || brand.name, Math.round(base * 0.085), t + 0.35, length - 0.35, a, { tone: plan.titleTone, tin: 'slideUp' }));
  } else if (s.caption) {
    const inset = length > 1.4 ? 0.25 : 0;
    textClips.push(mkText(s.caption, Math.round(base * 0.052), t + inset, length - inset * 2, s.captionPosition, { tin: 'slideUp' }));
    shownCaption = s.caption;
  }
  cleanShots.push({ clipId: c.id, start: trim, length, caption: shownCaption });
  lastSrc = src;
  lastClip = { dur, end: trim + length };
  t = r2(t + length);
}
if (!videoClips.length) throw new Error('No usable clips in request');

// 5. End card over the last shot, blurred and dimmed
const E = 3.2;
if (lastSrc) {
  let etrim = lastClip.end;
  if (etrim + E > lastClip.dur) etrim = Math.max(0, lastClip.dur - E);
  videoClips.push({ asset: { type: 'video', src: lastSrc, trim: r2(etrim), volume: 0 }, start: r2(t), length: r2(Math.min(E, lastClip.dur)), fit: 'cover', filter: 'blur', opacity: 0.45 });
}
const low = x => String(x || '').toLowerCase().replace(/[^a-z]/g, '');
let headline = plan.endLine || brand.tagline || brand.name || '';
if (brand.cta && low(headline) === low(brand.cta)) headline = brand.tagline || brand.name || headline;
if (brand.name) textClips.push(mkText(brand.name, Math.round(base * 0.03), t + 0.3, E - 0.3, 'center', { dy: 0.1, opacity: 0.85, h: 0.06 }));
if (headline) textClips.push(mkText(headline, Math.round(base * 0.075), t + 0.5, E - 0.5, 'center', { dy: 0.02, tin: 'slideUp' }));
if (brand.cta) textClips.push(mkText(brand.cta, Math.round(base * 0.034), t + 1.1, E - 1.1, 'center', { dy: -0.1, tone: 'dark', w: 0.46, h: 0.042, bg: { color: '#ffffff', opacity: 1, borderRadius: Math.round(base * 0.04), padding: 0 } }));
plan.shots = cleanShots;

// 6. Music
let musicUrl = null;
try { musicUrl = $input.first().json.secure_url || null; } catch (e) {}
const edit = {
  timeline: Object.assign({ background: '#000000', tracks: [{ clips: textClips }, { clips: videoClips }].concat(bgClips.length ? [{ clips: bgClips }] : []) }, musicUrl ? { soundtrack: { src: musicUrl, effect: 'fadeOut', volume: 0.8 } } : {}),
  output: { format: 'mp4', size: { width: W, height: H } }
};
return [{ json: { plan, director, music: !!musicUrl, edit } }];

const fallback = { summary: 'Energetic montage with hard cuts and bold captions', avgShotLength: 2, cutStyle: 'hard cuts', captionStyle: 'large, uppercase, bottom', colorMood: 'natural', musicMood: 'upbeat', structure: 'hook, montage, end card', transition: 'none', captionCase: 'upper', captionPosition: 'bottom', filter: 'none', editorNotes: '', shotLengthRange: [0.6, 3], pacing: 'builds', motion: 'dynamic', textUsage: 'sparse', musicGenre: 'upbeat indie pop', bpm: 120 };
let style = null;
try {
  const j = $input.first().json || {};
  const text = j.candidates[0].content.parts.map(p => p.text || '').join('');
  const m = text.match(/\{[\s\S]*\}/);
  style = Object.assign({}, fallback, JSON.parse(m ? m[0] : text));
  style.avgShotLength = Math.max(0.4, Math.min(5, Number(style.avgShotLength) || 2));
} catch (e) {}
return [{ json: { style: style || fallback, analysed: !!style } }];
